import {test} from 'node:test';import assert from 'node:assert/strict';import {locatorReason,locatorArrow,SWAP_LOCATOR_TICKS} from '../src/presentation/local-locator';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';
const f={active:true,swapTick:100}as any,v=(phase:string,tick=100)=>({phase,tick}as any);
test('locator appears only during countdown and after a local swap; hides at GO and during results',()=>{assert.equal(locatorReason(f,v('countdown')),'countdown');for(const phase of['announcement','round-results','match-results'])assert.equal(locatorReason(f,v(phase)),undefined);assert.equal(locatorReason({active:true}as any,v('playing')),undefined);assert.equal(locatorReason(f,v('playing',99)),undefined);assert.equal(locatorReason(f,v('playing',100)),'swap');assert.equal(locatorReason(f,v('playing',207)),'swap');assert.equal(locatorReason(f,v('playing',208)),undefined);assert.equal(SWAP_LOCATOR_TICKS,108);assert.equal(locatorReason({...f,swapTick:250},v('playing',250)),'swap');});
test('missing/local inactive/offline frog cannot create an indicator',()=>{for(const phase of['countdown','playing']){assert.equal(locatorReason(undefined,v(phase)),undefined);assert.equal(locatorReason({...f,active:false},v(phase)),undefined);assert.equal(locatorReason(f,v(phase),false),undefined);}assert.equal(locatorReason(f,undefined),undefined);});
test('arrow geometry points outside charge ring, stays within arena edges, and adapts to large frogs/mobile scale',()=>{for(const x of[20,600,1180])for(const y of[30,330,645])for(const r of[10.125,13.5,18.225])for(const scale of[1,2.5]){const a=locatorArrow(x,y,r,scale);assert.ok(Math.hypot(a.tip.x-x,a.tip.y-y)>r+9);assert.ok(a.points.every(p=>p.x>=0&&p.x<=1200&&p.y>=0&&p.y<=675));assert.ok(a.text.y>=18&&a.text.y<=652);}});
test('only the authorized rendering adapter changes; all other runtime bytes remain preserved',()=>{const m=JSON.parse(readFileSync('docs/local-locator-preservation.json','utf8')),h=(v:any)=>createHash('sha256').update(v).digest('hex');for(const[p,v]of Object.entries(m.protected))assert.equal(h(readFileSync(p)),v,p);for(const[p,v]of Object.entries(m.files)as[string,any][])assert.equal(h(readFileSync(p)),v.afterSha256,p);});
